module StreamEndpointTest

using RestClient
using JSON3, StructTypes
using Test
using Downloads

@jsondef struct Tok
    n::Int
end

# SSE, default termination (stop at EOF). Autogenerated SsechatEndpoint.
@endpoint ssechat() -> "sse" -> Stream{Tok}

# NDJSON via the two-parameter framing form. Autogenerated GenerateEndpoint.
@endpoint generate() -> "ndjson" -> Stream{Tok, :NDJSON}

# Whole-frame SSE: element type is SSEvent{Tok}.
@endpoint events() -> "sse" -> Stream{SSEvent{Tok}}

# Custom termination on the derived endpoint name (a `[DONE]` data sentinel).
@endpoint chatdone() -> "sse/done" -> Stream{Tok}
RestClient.isstreamend(::ChatdoneEndpoint, fr::SSEvent) = fr.data == codeunits("[DONE]")

# The same sentinel, but the server then keeps the connection open.
@endpoint lingering() -> "sse/done/open" -> Stream{Tok}
RestClient.isstreamend(::LingeringEndpoint, fr::SSEvent) = fr.data == codeunits("[DONE]")

# Custom termination via a terminal event type.
@endpoint chatstop() -> "sse/stop" -> Stream{Tok}
RestClient.isstreamend(::ChatstopEndpoint, fr::SSEvent) = fr.event == "stop"

# Rate-limited once: the POST is retried, payload and all, before streaming.
@endpoint limitedchat(; prompt::String) -> prompt -> "sse/limited" -> Stream{Tok}

# One frame, then silence (STALL_SECONDS) before the next.
@endpoint stalling() -> "stall" -> Stream{Tok, :NDJSON}

# SSE heartbeats 3 s apart, sparser than 1 byte/s but never silent for 4 s.
@endpoint heartbeat() -> "heartbeat" -> Stream{Tok}

# Four frames a second apart: longer overall than a 2 s timeout, but never silent for it.
@endpoint steady() -> "steady" -> Stream{Tok, :NDJSON}

# An error status before any frame: should raise with the body, not stream.
@endpoint failing() -> "error500" -> Stream{Tok}

function run(base)
    cfg = RequestConfig(base)
    @testset "supertype inference" begin
        @test SsechatEndpoint <: RestClient.StreamEndpoint
        @test GenerateEndpoint <: RestClient.StreamEndpoint
        @test EventsEndpoint <: RestClient.StreamEndpoint
        @test responsetype(SsechatEndpoint()) === Stream{Tok}
        @test responsetype(GenerateEndpoint()) === Stream{Tok, :NDJSON}
    end
    @testset "SSE" begin
        s = ssechat(cfg)
        @test s isa Stream{Tok}
        @test collect(s) == [Tok(n=1), Tok(n=2), Tok(n=3)]
    end
    @testset "NDJSON" begin
        @test collect(generate(cfg)) == [Tok(n=1), Tok(n=2), Tok(n=3)]
    end
    @testset "whole frames" begin
        evs = collect(events(cfg))
        @test all(e -> e isa SSEvent{Tok}, evs)
        @test evs[1].event == "tick" && evs[1].id == "a"
        @test [e.data for e in evs] == [Tok(n=1), Tok(n=2), Tok(n=3)]
        # destructuring (event, data)
        for (ev, tok) in events(cfg)
            @test tok isa Tok
        end
    end
    @testset "custom end" begin
        @test collect(chatdone(cfg)) == [Tok(n=1)]          # stops at [DONE]
        # ...even if the server doesn't close the connection
        t = @elapsed @test collect(lingering(cfg)) == [Tok(n=1)]
        @test t < 5                                          # the server holds it open for 10 s
        @test collect(chatstop(cfg)) == [Tok(n=1)]          # stops at event: stop
    end
    @testset "rate-limited" begin
        @test collect(limitedchat(cfg, prompt = "hi")) == [Tok(n=1), Tok(n=2), Tok(n=3)]
    end
    @testset "timeout bounds silence" begin
        quick = RequestConfig(base; timeout = 1)
        # Silence beyond the timeout abandons the stream after the first frame...
        got = Tok[]
        t = @elapsed @test_throws RestClient.IdleTimeout for tok in stalling(quick)
            push!(got, tok)
        end
        @test got == [Tok(n=1)]
        @test t < 3                                          # promptly, not after the stall
        # ...but a stream that keeps sending outlives it.
        @test collect(steady(RequestConfig(base; timeout = 2))) == [Tok(n=i) for i in 1:4]
        # Heartbeats are data, however sparse
        @test collect(heartbeat(RequestConfig(base; timeout = 4))) == [Tok(n=1), Tok(n=2)]
    end
    @testset "error status" begin
        @test_throws RestClient.ResponseError failing(cfg)
        err = try failing(cfg) catch e; e end
        @test err isa RestClient.ResponseError
        @test err.response.status == 500
        @test err.body == codeunits("boom")
    end
    @testset "cancellation" begin
        s = ssechat(cfg)
        for tok in s
            close(s)                                        # bail after first frame
            break
        end
        @test true
    end
end

end  # module
